tw.local.oldTaskID = "";
if(tw.local.reasonsLog == null || tw.local.reasonsLog.listLength==0)
{
	tw.local.reasonsLog = new tw.object.listOf.ReturnedReasonsLog();

}
else
{
	var index = tw.local.reasonsLog.listLength -1;
	if(index >= 0)
	{
		var from = tw.local.reasonsLog[index].fromUserRole.replace("MKR","CHKR");
		if((tw.local.reasonsLog[index].toUser == null || tw.local.reasonsLog[index].toUser == "") && tw.local.fromUserRole == from)
		{
			tw.local.oldTaskID = tw.local.reasonsLog[index].taskID;
			 tw.local.reasonsLog[index].taskID = tw.local.taskID; 
		}
	}
}

var fromUser = tw.system.user_fullName+"("+ tw.system.user_loginName+")";
var day = new Date().getDate();
var month = new Date().getMonth() + 1;
var year = new Date().getFullYear();
var date = day.toString() + "/" + month.toString() + "/" + year.toString();
var min = new Date().getMinutes().toString();
if(min.length == 1)
{
	min = "0"+min;
}
var time = new Date().getHours().toString()+ ":" + min  ;


if(tw.local.reasonsLog == null)
{
	tw.local.reasonsLog = new tw.object.listOf.ReturnedReasonsLog();
}
else
{
	for (var i=0; i<tw.local.reasonsLog.listLength; i++) 
	{
		if(tw.local.reasonsLog[i].toUser == null || tw.local.reasonsLog[i].toUser == "")
		{
			tw.local.reasonsLog.removeIndex(i--);
		}
	}
}
var len = tw.local.reasonsLog.listLength;
if(tw.local.returnedReasons != null && tw.local.returnedReasons.listLength > 0 && tw.local.action != "approve" )
{
	
	for (var i=0; i<tw.local.returnedReasons.listLength; i++) 
	{
		var reasonObj = new tw.object.ReturnedReasonsLog();
		reasonObj.date = date;
		reasonObj.time = time;
		reasonObj.stepName = tw.local.stepName;
		reasonObj.fromUser = fromUser;
		reasonObj.fromUserRole = tw.local.fromUserRole;
		reasonObj.toUserRole = tw.local.toUserRole; 
		
		var from ="";
		if(tw.local.fromUserRole!=null && tw.local.fromUserRole!=''){
			from=tw.local.fromUserRole.replace("_MKR"," Maker");
			from =from.replace("_CHKR"," Checker");
			from =from.replace("_"," ");
			from =from.replace("_"," ");
		}
		
		
		var to=""
		if(tw.local.toUserRole!=null && tw.local.toUserRole!=''){
			to =tw.local.toUserRole.replace("_MKR"," Maker");
			to =to.replace("_CHKR"," Checker");
			to =to.replace("_"," ");
			to =to.replace("_"," ");
		
	    }
		reasonObj.fromUserRoleName = from;
		reasonObj.toUserRoleName = to; 
		reasonObj.Reason = tw.local.returnedReasons[i].name;
		reasonObj.taskID = tw.local.taskID;
		tw.local.reasonsLog.insertIntoList(len++, reasonObj);	
	}
}

