function checkCusstomerType(type) {


    if (tw.local.LGAmendmentRequest.LGforTheAccountInformation.customerInfo.customerType.value == type && (
        tw.local.LGAmendmentRequest.LGforTheAccountInformation.lgNatureType.value == "FACILITY"||
        tw.local.LGAmendmentRequest.amendmentOptions.chengeOptions.changeFacility==true
        || (tw.local.LGAmendmentRequest.amendmentOptions.chengeOptions.changeLGNature==true &&
        tw.local.LGAmendmentRequest.NatureOfLG!=null &&tw.local.LGAmendmentRequest.NatureOfLG =='التعديل الي تسهيلات ائتمانية'        )
        )
        ) {
        return true;
    }
    return false;
}

function checkFacilityLineIsExpired() {
    if (tw.local.Facilities != null && tw.local.Facilities.listLength > 0) {
        var date1 = new Date();
        for (var i = 0; i < tw.local.Facilities.listLength; i++) {
            if (tw.local.Facilities[i].facilityLine == null ) {
            	tw.local.errorMessage += "Can't retrive faci;ity line for facility : "+ tw.local.Facilities[i].cif;
            	return false;
            }
            var facilityDate = tw.local.Facilities[i].facilityLine.expiryDate;
            facilityDate = facilityDate.split('-')[1] + "/" + facilityDate.split('-')[0] + "/" + facilityDate.split('-')[2];
            var date2 = new Date(facilityDate);
            var diffTime = date2 - date1;
            var diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            if (diffDays < 0) {
                return true;
            }
        }
    }
    return false;
}

//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
function checkExpiryDate() {
    var newExpiryDate = tw.local.LGAmendmentRequest.chengeExpiryDate.newExpiryDate;
    var contractDate = new Date();
    var diffrence = newExpiryDate - contractDate;
    diffrence = diffrence / (1000 * 60 * 60 * 24) + 1;
    if (diffrence > 364) {
        return true;
    }
    return false;
}
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
function checkAdvancedPayment() {
    tw.local.tmpValue = tw.epv.AmendmentOptionDetails.AdvancePayment;
    if (tw.local.tmpValue.indexOf(tw.local.LGAmendmentRequest.LGBasicInformation.contractDetails.lgType.value) > -1) {
        return true;
    }
    return false;
}
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
function chcekcIfJV() {
    var JVlength = tw.local.LGAmendmentRequest.changeLGOrderingAccountee.JVCustomers.listLength;
    var OldJVLength = tw.local.LGAmendmentRequest.LGBasicInformation.contractDetails.Contract_Limits.listLength;
    if (JVlength > 0 && tw.local.AmendSectionsVisibilty.changeLGOrderingAccounteeVis.toLocaleLowerCase() != "none") {
        for (var i = 0; i < tw.local.Facilities.listLength; i++) {
            for (var j = 0; j < JVlength; j++) {
                if (tw.local.Facilities[i].cif == tw.local.LGAmendmentRequest.changeLGOrderingAccountee.JVCustomers[j].customerNo) {
                    return true;
                }
            }
        }
    } else if (OldJVLength > 0) {
        for (var i = 0; i < tw.local.Facilities.listLength; i++) {
            for (var j = 0; j < OldJVLength; j++) {
                if (tw.local.Facilities[i].cif == tw.local.LGAmendmentRequest.LGBasicInformation.contractDetails.Contract_Limits[j].CustomerNo &&
                    (tw.local.LGAmendmentRequest.LGBasicInformation.contractDetails.Contract_Limits[i].JVPARENT != null &&
                        tw.local.LGAmendmentRequest.LGBasicInformation.contractDetails.Contract_Limits[j].JVPARENT != "")) {
                    return true;
                }
            }
        }
    }
    return false;
}
