scripts.script:
tw.local.sendTo = "NoCAD";

if(tw.local.amendmentDetails != null && tw.local.amendmentDetails.recommendedApprovals != null && tw.local.amendmentDetails.recommendedApprovals.CAD)
{

if(tw.local.amendmentDetails.amendmentOptions.chengeOptions.changeOrderingAcc)
{
	CheckCustomerType(tw.local.amendmentDetails.changeLGOrderingAccountee.customerInfo.customerType.value)
	
}else {
		var flag = false;
		try {
			flag = tw.local.amendmentDetails.LGAmendmentOriginalRequestDetails!=null && tw.local.amendmentDetails.LGAmendmentOriginalRequestDetails.LGOrderingAccountee!=null &&
			tw.local.amendmentDetails.LGAmendmentOriginalRequestDetails.LGOrderingAccountee.customerType!=null && 
			tw.local.amendmentDetails.LGAmendmentOriginalRequestDetails.LGOrderingAccountee.customerType.value!=null && 
			tw.local.amendmentDetails.LGAmendmentOriginalRequestDetails.LGOrderingAccountee.customerType.value!=''
		} catch (err) {
			flag = false;
		}
		if(flag)		
			CheckCustomerType(tw.local.amendmentDetails.LGAmendmentOriginalRequestDetails.LGOrderingAccountee.customerType.value);
		else{			
			CheckCustomerType(tw.local.amendmentDetails.LGforTheAccountInformation.customerInfo.customerType.value)
		}
	}	
}

function CheckCustomerType(value)
{
	if (value == tw.epv.AmendmentAction.Retail)
	{
		tw.local.sendTo = "CC";
	}
	else
	{
		tw.local.sendTo = "CAD";
	}
}

var lgCategory = tw.local.AmendmentDetails.LGBasicInformation.contractDetails.lgCategory.value 

if(tw.local.afterParallel)
{
	if(tw.local.action == tw.epv.AmendmentAction.Approve)
	{
		tw.local.sendTo = "BE EXE";
	}
	else
	{
		if(lgCategory == tw.epv.AmendmentAction.Foreign)
		{
			tw.local.sendTo = "BE";
		}
		else
		{
			tw.local.sendTo = "FE";
		}
	}
}
else
{
	if(tw.local.action == tw.epv.AmendmentAction.Return)
	{
		tw.local.sendTo = "Branch";
	}
	else
	{
		if(lgCategory == tw.epv.AmendmentAction.Foreign)
		{
			tw.local.sendTo = "BE";
		}
		else
		{
			tw.local.sendTo = "FE";
		}
	}
}

