tw.local.notAgain = false;
if(tw.local.existCurrency.listLength > 0)
{
	for (var i=0; i< tw.local.existCurrency.listLength; i++) 
	{
		if(tw.local.existCurrency[i] == tw.local.facilities[tw.local.Index].facilityLine.lineCurrency)
		{
			tw.local.notAgain = true;
			tw.local.facilityAmount += tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount * tw.local.existRate[i];
			break;
		}
	}
}

function writeLog(msg , variable){  // vairable is optional
	var instanceID = "";
	try {instanceID = "Instance ID : "+tw.system.currentProcessInstance.id  +"  ::  ";} catch (err) {}
	variable == undefined ? variable =" " : variable = " : "+ variable ;
	var message = instanceID + tw.system.model.processApp.name  +" :: " + tw.system.serviceFlow.type +" :: "+ tw.system.serviceFlow.name +" :: "  + msg+" : " + variable;
	log.info( message);
}

tw.local.facilityLessThanAmount = false;
tw.local.isSuccessful = true;
var allfacilitypercentage = 0 ;

writeLog("befor looping on facilities");
writeLog("tw.local.checkBalance" , tw.local.checkBalance)
for (var i = 0; i < tw.local.facilities.listLength; i++) {
    allfacilitypercentage += tw.local.facilities[i].facilityLine.facilityPercentage;
    tw.local.perForFacilityAmount = percentage(tw.local.LGequivalentAmountInEGP, tw.local.facilities[i].facilityLine.facilityPercentage);  // new update


    if (tw.local.perForFacilityAmount > tw.local.facilities[i].facilityLine.avaliableAmountEGP) {
        tw.local.facilityLessThanAmount = true;
        if (tw.local.checkBalance) {
	         tw.local.errorMsg +=  tw.resource.IssuanceLK.TheFacilityRateFromLGAmountMustBeEqualOrLessEnglish + " for facility Liability number " + tw.local.facilities[i].cif +
	            " <br> &nbsp;&nbsp;&nbsp;&nbsp;" + tw.resource.IssuanceLK.TheFacilityRateFromLGAmountMustBeEqualOrLessArabic;       	
        }

    }
    if (tw.local.checkBalance) {
	    checkExpiry(tw.local.facilities[i].facilityLine.expiryDate);
	    checkAvailableFlag (tw.local.facilities[i].facilityLine.availableFlag);
	    if (tw.local.facilities[i].facilityObjectData != null) {
	    	checkAuthFlag (tw.local.facilities[i].facilityObjectData.authorizedFlag)    	    	
	    }

    }
}


// check if facility percentage is 100%
if (allfacilitypercentage != 100 ) {

    tw.local.errorMsg += "<li> "+tw.resource.IssuanceLK.Pleaseentervaliddataandensurethatthetotal+" </li>";
}


//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function checkExpiry (facilityDate) {
	var date1 = new Date();
	facilityDate = facilityDate.split('-')[1] + "/" + facilityDate.split('-')[0] + "/" + facilityDate.split('-')[2];
	var date2 = new Date(facilityDate);
	var diffTime = date2 - date1;
	var diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
	if (diffDays < 0) {
		tw.local.errorMsg += "<li>" + tw.resource.IssuanceLK.ErrorFacilityExpired + "</li>";
	}
}
function checkAuthFlag(authorizedFlag) {
	if(!authorizedFlag)
		{
		tw.local.errorMsg += "<li>" + tw.resource.IssuanceLK.ErrorFacilityIsUnauthorized + "</li>";
	}	
}
function checkAvailableFlag (availableFlag) {
	if(!availableFlag)
		{
		tw.local.errorMsg += "<li>" + tw.resource.IssuanceLK.ErrorFacilityIsUnavailable + "</li>";
	}	
}

function percentage(num, per) {
    return (num / 100) * per;
}

function writeLog(msg, variable) { // vairable is optional
    var instanceID = "";
    try {
        instanceID = "Instance ID : " + tw.system.currentProcessInstance.id + "  ::  ";
    } catch (err) {}
	    variable == undefined ? variable = " " : variable = " : " + variable;
	    var message = instanceID + tw.system.model.processApp.name + " :: " + tw.system.serviceFlow.type + " :: " + tw.system.serviceFlow.name + " :: " + msg + " : " + variable;
	    log.info(message);
}

tw.local.facilityLessThanAmount = false;
tw.local.serviceLog.insertIntoList(tw.local.serviceLog.listLength, "LGequivalentAmountInEGP " + tw.local.LGequivalentAmountInEGP);
tw.local.serviceLog.insertIntoList(tw.local.serviceLog.listLength, " percentage(tw.local.LGequivalentAmountInEGP ,tw.local.cashCoverPer)  " + percentage(tw.local.LGequivalentAmountInEGP, tw.local.cashCoverPer));


tw.local.perForFacilityAmount = tw.local.LGequivalentAmountInEGP - percentage(tw.local.LGequivalentAmountInEGP, tw.local.cashCoverPer);
tw.local.serviceLog.insertIntoList(tw.local.serviceLog.listLength, "perForFacilityAmount  " + tw.local.perForFacilityAmount);
writeLog(" ::::::::: check the facility" + tw.local.perForFacilityAmount > tw.local.facilityAmount);
if (tw.local.check)
    tw.local.checkBalance = tw.local.check;
else
    tw.local.checkBalance = tw.epv.ProcessDetails.CheckFacilitiesBalance;

tw.local.serviceLog.insertIntoList(tw.local.serviceLog.listLength, "checkBalance " + tw.local.checkBalance);
if (tw.local.perForFacilityAmount > tw.local.facilityAmount && tw.local.checkBalance) {
    tw.local.facilityLessThanAmount = true;
    tw.local.errorMsg += "<li>" + tw.resource.IssuanceLK.TheFacilityRateFromLGAmountMustBeEqualOrLessEnglish + "<br> &nbsp;&nbsp;&nbsp;&nbsp;" + tw.resource.IssuanceLK.TheFacilityRateFromLGAmountMustBeEqualOrLessArabic + "</li>";
    //" <li>The facility rate from the LG amount must be equal or less than the facility amount - نسبة التسهيلات لمبلغ خطاب الضمان يجب ان تساوى او تقل عن رصيد حساب التسهيلات </li>"
}


