	var instanceID = "";
	try {instanceID = "Instance ID : "+tw.system.currentProcessInstance.id  +"  ::  ";} catch (err) {}
	variable == undefined ? variable =" " : variable = " : "+ variable ;
	var message = instanceID + tw.system.model.processApp.name  +" :: " + tw.system.serviceFlow.type +" :: "+ tw.system.serviceFlow.name +" :: "  + msg+" : " + variable;
	log.info( message);
}

log.info("tw.local.versionNumber "+tw.local.versionNumber)
log.info("tw.local.isSuccessful "+tw.local.isSuccessful)
log.info(" tw.local.errorMsg "+tw.local.errorMsg)

//if(tw.local.versionNo != null && tw.local.versionNo != "" && tw.local.versionNo == "0")
if(tw.local.isSuccessful==true)
{
	//tw.local.versionNumber = Number(tw.local.versionNo);
}
else
{
	tw.local.isSuccessful = false;
	tw.local.versionNumber = 0;
	if(tw.local.errorMsg!=null && tw.local.errorMsg.length > 0)
		tw.local.errorMsg = "<li>"+tw.local.errorMsg+"</li>";
	else
		tw.local.errorMsg = "<li>"+"Retry, integration is failed"+"</li>";
}

tw.local.isSuccessful = false;
//tw.local.versionNumber = 0; 
if(tw.local.errorMsg!=null && tw.local.errorMsg.length > 0)
	tw.local.errorMsg = "<li>"+tw.local.errorMsg+"</li>";
else
	tw.local.errorMsg = "<li>"+"Retry, integration is failed"+"</li>";

writeLog("Error In "+tw.local.logError+" Service,Message : "+tw.system.error);

function writeLog(msg , variable){  // vairable is optional
	var instanceID = "";
	try {instanceID = "Instance ID : "+tw.system.currentProcessInstance.id  +"  ::  ";} catch (err) {}
	variable == undefined ? variable =" " : variable = " : "+ variable ;
	var message = instanceID + tw.system.model.processApp.name  +" :: " + tw.system.serviceFlow.type +" :: "+ tw.system.serviceFlow.name +" :: "  + msg+" : " + variable;
	log.info( message);
}

writeLog("tw.local.isSuccessful " + tw.local.isSuccessful)

if (tw.local.lgAmendmentDetails == null) {
    tw.local.isSuccessful = false;
} else {
    if (tw.local.lgAmendmentDetails.amendmentOptions.changeType == tw.epv.AmendmentOptionsList.Cancel) {
        tw.local.action = "cancel";
        tw.local.cancelGuaranteeFlag = true;
    } else if (tw.local.lgAmendmentDetails.amendmentOptions.changeType == tw.epv.AmendmentOptionsList.Close) {
        tw.local.action = "close";
        tw.local.cancelGuaranteeFlag = false;
    } else if (tw.local.lgAmendmentDetails.amendmentOptions.changeType == tw.epv.AmendmentOptionsList.Liquidation) {
        tw.local.action = "liquidate";
        tw.local.amount = tw.local.lgAmendmentDetails.ChangeLGLiquidation.liquidateAmount;
        writeLog("liquidate amount " + tw.local.amount)
        tw.local.trackLimit = CheckTrackLimit();
        GetAccountInformation();

    } else if (tw.local.lgAmendmentDetails.amendmentOptions.changeType == tw.epv.AmendmentOptionsList.Reverse) {
        tw.local.action = "reverse";
    } else // For Update LG Contract data
    {
        GetAccountInformation();
        if (tw.local.lgAmendmentDetails.amendmentOptions.chengeOptions.reopenLG && tw.local.reopenUpdated == "check") {
            tw.local.action = "reopen";
            tw.local.amount = tw.local.lgAmendmentDetails.LGBasicInformation.contractDetails.amount;
        }
        if (tw.local.lgAmendmentDetails.amendBackEnd && tw.local.reopenUpdated != "check") {
            tw.local.action = "amend";
            tw.local.amount = GetAmount();
            GetCIF();
            GetExpiryDate();
            GetPartyDetails();
        } else if (tw.local.reopenUpdated != "check") {
            tw.local.action = "modify";
            tw.local.amount = GetAmount();
            GetFacilityData();
            GetCIF();
            GetExpiryDate();
            GetPartyDetails();
        }
        if (tw.local.lgAmendmentDetails.amendmentOptions.chengeOptions.LGLiquidation && tw.local.reopenUpdated != "check") {
            if (tw.local.lgAmendmentDetails.finalAmendmentType == tw.epv.AmendmentOptionsList.Liquidation) {
                tw.local.action = "liquidate";
                tw.local.amount = tw.local.lgAmendmentDetails.ChangeLGLiquidation.liquidateAmount;
            }
        } else if (IsLiquidateOnly()) {
            tw.local.action = "liquidate";
            GetAccountInformation();
            tw.local.amount = tw.local.lgAmendmentDetails.ChangeLGLiquidation.liquidateAmount;
        }
    }
    tw.local.trackLimit = CheckTrackLimit();
    if (tw.local.action == "reopen" || tw.local.action == "liquidate") {
        if (tw.local.lgAmendmentDetails.LGBasicInformation.contractDetails.Contract_Limits != null && tw.local.lgAmendmentDetails.LGBasicInformation.contractDetails.Contract_Limits.listLength > 0)
            tw.local.trackLimit = "Y";
        else
            tw.local.trackLimit = "N";
    }


}


writeLog("amend option tw.local.action " + tw.local.action);
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function CheckTrackLimit() {
    if (tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData.listLength > 0)
        return "Y";
    else if (tw.local.lgAmendmentDetails.LGforTheAccountInformation.lgNatureType.value == "FACILITY")
        return "Y";
    else
        return "N";
}


function GetCIF() {
    if (tw.local.lgAmendmentDetails.changeLGOrderingAccountee != null && tw.local.lgAmendmentDetails.changeLGOrderingAccountee.customerInfo != null && tw.local.lgAmendmentDetails.changeLGOrderingAccountee.customerInfo.customerNo != null && tw.local.lgAmendmentDetails.changeLGOrderingAccountee.customerInfo.customerNo != "") {
        tw.local.accounteeFlag = true;
        tw.local.accounteeDetails = {}
        tw.local.accounteeDetails.cif = tw.local.lgAmendmentDetails.changeLGOrderingAccountee.customerInfo.customerNo;
        writeLog("tw.local.accounteeDetails.cif " + tw.local.accounteeDetails.cif)
        tw.local.accounteeDetails.name = tw.local.lgAmendmentDetails.changeLGOrderingAccountee.customerInfo.customerName;
        writeLog("tw.local.accounteeDetails.name " + tw.local.accounteeDetails.name)
    }
}

function GetAmount() {
    if (tw.local.lgAmendmentDetails.amendmentOptions.chengeOptions.changeLGAmount)
        return tw.local.lgAmendmentDetails.changeLGAmount.newOutstandingAmount;
    else
        return tw.local.lgAmendmentDetails.LGBasicInformation.contractDetails.amount;
}

function GetExpiryDate() {
    if (tw.local.amendmentSectionsVisibilty.chengeExpiryDateVis.toLocaleLowerCase() != "none" &&
        tw.local.lgAmendmentDetails.chengeExpiryDate != null && tw.local.lgAmendmentDetails.chengeExpiryDate.newExpiryDate != null) {
        tw.local.expiryDate = tw.local.lgAmendmentDetails.chengeExpiryDate.newExpiryDate;
    } else {
        var parts = tw.local.lgAmendmentDetails.LGBasicInformation.contractDetails.expiryDate.split('/');
        if (parts != null && parts.length > 2) {
            var day = Number(parts[0])
            writeLog("day " + day)
            var month = Number(parts[1]) - 1;
            writeLog("month " + month)
            var year = Number(parts[2])
            writeLog("year " + year)
            tw.local.expiryDate = new Date();
            tw.local.expiryDate.setFullYear(year);
            tw.local.expiryDate.setMonth(month);
            tw.local.expiryDate.setDate(day);
        }

    }
}


function GetAccountInformation() {
    if (tw.local.lgAmendmentDetails.changeAccounts != null && tw.local.lgAmendmentDetails.changeAccounts.accountInformation != null &&
    	  tw.local.lgAmendmentDetails.changeAccounts.accountInformation.customerNo != null && tw.local.lgAmendmentDetails.changeAccounts.accountInformation.customerNo != "") {
	        tw.local.accountInformation = tw.local.lgAmendmentDetails.changeAccounts.accountInformation;
	        tw.local.accountInformation.collateralCurrency = tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.AccountInformation.collateralCurrency;
    } else {
        tw.local.accountInformation = tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.AccountInformation;
    }
}

function GetFacilityData() {
log.info("GetFacilityData")
    if (tw.local.lgAmendmentDetails.ChangeFacility != null && tw.local.lgAmendmentDetails.ChangeFacility.FacilityData != null && tw.local.lgAmendmentDetails.ChangeFacility.FacilityData.listLength > 0
    && tw.local.amendmentSectionsVisibilty.ChangeFacilityVis.toLowerCase() != "none")
        tw.local.facilityData = tw.local.lgAmendmentDetails.ChangeFacility.FacilityData;
    else {
        tw.local.facilityData = [];
        if (tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData!= null) {
		writeLog(tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData)
            for (var i = 0; i < tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData.listLength; i++) {
             tw.local.facilityData[i]={}
			tw.local.facilityData[i].cif=tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData[i].cif
			tw.local.facilityData[i].facilityPercentage=tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData[i].facilityLine.facilityPercentage
			tw.local.facilityData[i].facilityCode={};
			tw.local.facilityData[i].facilityCode.name = tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData[i].facilityLine.lineCode
			tw.local.facilityData[i].lineSerialNumber = tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData[i].facilityLine.lineSeriial
			tw.local.facilityData[i].parentCIF=tw.local.lgAmendmentDetails.LGAmendmentOriginalRequestDetails.FacilityData[i].parentCIF
	            }


        }
    }
    log.info("get the updated facility")
    writeLog(tw.local.facilityData )
}

