function checkAction(action, appLogList, returnLogList) {
    if (tw.local.action != tw.epv.AmendmentAction.Return) {
        tw.local.action = action;
    }
    addAppLog(appLogList);
    addReturn(returnLogList);

}

function addReturn(returnLogList) {
	if (returnLogList == null || returnLogList.length == 0) {
		return 0;
	}
    for (var i = returnLogLen; i < returnLogList.length; i++) {
        tw.local.LGAmendmentRequest.returnReasonsLog.insertIntoList(tw.local.LGAmendmentRequest.returnReasonsLog.listLength, returnLogList[i]);
        if (!returnLogList[i].toUser) {
            tw.local.returnReasonList[index] = new tw.object.NameValuePair();
            tw.local.returnReasonList[index].name = returnLogList[i].Reason;
            tw.local.returnReasonList[index++].value = returnLogList[i].Reason;
        }
    }

}

