function checkbalanceforfacility()
{
 		var cashamount = percentage(tw.local.LGequivalentAmountInEGP ,tw.local.cashCoverPer);

 		writeLog( "  cashamount is : "+cashamount);
		if (cashamount > tw.local.equivalentAmountInEGP) {
			tw.local.ErrorMsg += "<li>"+tw.resource.IssuanceLK.theCashCoverRateFromLGAmountMustbeLesssMoreThanCashCoverEnglish+"<br> &nbsp;&nbsp;&nbsp;&nbsp;"+tw.resource.IssuanceLK.TheCashCaverRateFromLGAmountMustBelessMorethanCashCoverArabic+"</li>";
			//"<li>The cash cover rate from the LG amount must be equal or less than the cash cover account balance - نسبة الغطاء النقدى لمبلغ خطاب الضمان يجب ان تساوى او تقل عن رصيد حساب الغطاء النقدي </li>"
