function getUserRole() {
   if (!tw.system.org.findUserByName(tw.local.userID).isInRole(tw.local.groupName)) {
      tw.local.groupName = "";
      return;
   }
   var index = 0;
   var flag = true;
   var assignedTeamGroups = [];
   while (flag && index < 10) {
      index++;
      try {
         assignedTeamGroups = tw.system.org.findRoleByName(tw.local.groupName).roles;
         assignedTeamGroups.listLength > 0 ? flag = true : false;
      } catch (err) {
         flag = false;
      }
      for (var i = 0; i < assignedTeamGroups.listLength && flag; i++) {
         if (tw.system.org.findUserByName(tw.local.userID).isInRole(assignedTeamGroups[i])) {
            tw.local.groupName = assignedTeamGroups[i].name;
            break;
         }
      }
   }
}

function getUserBranch() {
   var userRoles = tw.system.org.findUserByName(tw.local.userID).roles;
   var regx = /['BR']\d{3}/;
   for (var i = 0; i < userRoles.length; i++) {
      writeLog(userRoles[i].name)
      if (regx.test(userRoles[i])) {
         return userRoles[i].name;
      }
   }
   return "";
}

function writeLog(msg, variable) { // vairable is optional
   var instanceID = "";
   try {
      instanceID = "Instance ID : " + tw.system.currentProcessInstance.id + "  ::  ";
   } catch (err) {}
   variable == undefined ? variable = " " : variable = " : " + variable;
   var message = instanceID + tw.system.model.processApp.name + " :: " + tw.system.serviceFlow.type + " :: " + tw.system.serviceFlow.name + " :: " + msg + " : " + variable;
   log.info(message);
}

