// Processes facilities based on CIF
function processFacilitiesBasedOnCIF() {
    var contractDetails = tw.local.LGAmendmentRequest.LGBasicInformation.contractDetails;
    var CutomerCIF = contractDetails.customerNo;
    var Accountee = determineAccountee(contractDetails);
    var joinList = determineJoinList(Accountee, contractDetails);
    validateFacilities( CutomerCIF , Accountee ,joinList);
}
// Determine Accountee based on amendment options and contract details
function determineAccountee(contractDetails) {
    var Accountee = ""
    if (tw.local.LGAmendmentRequest.amendmentOptions.chengeOptions.changeOrderingAcc) {
        try {
            Accountee = tw.local.LGAmendmentRequest.changeLGOrderingAccountee.customerInfo.customerNo;
        } catch (err) {}
    } else {
        if (contractDetails.PartyDetails != null) {
            for (var i = 0; i < contractDetails.PartyDetails.length; i++) {
                if (contractDetails.PartyDetails[i].type.toLowerCase() == "acc") {
                    return contractDetails.PartyDetails[i].cif;
                }
            }
        }
    }
    return Accountee;
}
// Determine join list based on Accountee and contract details
