    var joinList = [];
    var amendmentRequest = tw.local.LGAmendmentRequest;
    // Check if there's a need to change ordering account
    if (amendmentRequest.amendmentOptions.chengeOptions.changeOrderingAcc) {
        var JVCustomers = amendmentRequest.changeLGOrderingAccountee.JVCustomers;
        
        // Ensure JVCustomers is not null and has elements
        if (JVCustomers && JVCustomers.length > 0) {
            for (var i = 0; i < JVCustomers.length; i++) {
                joinList.push(JVCustomers[i].customerNo);         
        	}
	  }	 
