function getTenor(){

	tw.local.lgRequestDetails.transactionInformation.expiryDate = setNewDate(tw.local.lgRequestDetails.transactionInformation.expiryDate)
	tw.local.lgRequestDetails.transactionInformation.effectiveDate = setNewDate(tw.local.lgRequestDetails.transactionInformation.effectiveDate)
	var Difference_In_Time = tw.local.lgRequestDetails.transactionInformation.expiryDate - tw.local.lgRequestDetails.transactionInformation.effectiveDate;
	return  parseInt(Difference_In_Time / (1000 * 3600 * 24));

}
function setNewDate (date) {
	var year = date.getFullYear();
	var month = date.getMonth();
	var day = date.getDate();
	return new Date(year, month, day);
}

function setDateStr(date) {
    date.setHours(date.getHours() + 1);
    var day =(date.getDate() )+ "";
    var month = (date.getMonth() + 1) + "";
    if (day.length < 2)
        day = "0" + day;
    if (month.length < 2)
        month = "0" + month;

    return date.getFullYear() + "-" + month + "-" + day;
}



function getNumber (val) {
	if (val  < 10) {
		return "0"+val;
	}
	return val;
}

