	var tmpauth = false;
	for (var j=0; j<tw.local.document.properties.length; j++) {
		if(tw.local.document.properties[j].objectTypeId == tw.local.data.Properties[i].objectTypeId && tw.local.document.properties[j].value == tw.local.data.Properties[i].value)
