} 


tw.local.SQLStatement[0].sql = tw.local.SQLCommand.slice(0, -1) + " where INSTANCE_ID = ? "  
AddParameter(null , tw.local.InstanceID ,false);


function AddParameter(attribute , value , flag) {
//   writeLog("current value "+ attribute +"   ",value);
   flag == undefined ? flag =true : 1 ;
   tw.local.SQLStatement[0].parameters[index] = new tw.object.SQLParameter();
   tw.local.SQLStatement[0].parameters[index].value = checkValue(value);
   tw.local.SQLStatement[0].parameters[index++].mode = "IN";
   if (flag) {
   	tw.local.SQLCommand = tw.local.SQLCommand + attribute + " = ?,";
   }
}

function checkValue(objectValue) {
   var value = objectValue;
   if (value == null) {
   	return "";
   }
   try {
      if (objectValue.value != null && objectValue.value != undefined) {
         value = objectValue.value;
      }
   } catch (err) {}
   return value;
}


function writeLog(msg , variable){  // vairable is optional
	var instanceID = "";
	try {instanceID = "Instance ID : "+tw.system.currentProcessInstance.id  +"  ::  ";} catch (err) {}
	variable == undefined ? variable =" " : variable = " : "+ variable ;
	var message = instanceID + tw.system.model.processApp.name  +" :: " + tw.system.serviceFlow.type +" :: "+ tw.system.serviceFlow.name +" :: "  + msg+" : " + variable;
	log.info( message);
}

