 ,barcode ,  folder_id,  folder_path ,  main_Category_code,  main_type_code,   customer_category_code, \
 customer_type_code,  LG_category_code,  LG_type_code   ,LG_nature_code,  LG_nature_name \
 ,  cash_cover_percentage,  counter_currency_code,counter_amount,  LG_customer_type_code \
, LG_customer_type_name ,   special_Text_Flag,   previous_approval_number,  TASK_ID ,Process_Suffix,Process_Name ,version_no \
)  VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";

tw.local.SQLStatement[0] = new tw.object.SQLStatement();
