var index = 0;

if (tw.local.lgReprintDetails.appInfo.requestDate == "") {
   var requestDate = new TWDate();
} else {
   var parts = tw.local.lgReprintDetails.appInfo.requestDate.split('/');
   var requestDate = new Date(parseInt(parts[2]), parseInt(parts[1]) - 1, parseInt(parts[0]), 2, 0);
}
var Index = tw.local.lgReprintDetails.appInfo.initiator.indexOf("_");
if (Index == -1) {
   var Name = tw.local.lgReprintDetails.appInfo.initiator;
   var ID = tw.local.lgReprintDetails.appInfo.initiator;
} else {
   var ID = tw.local.lgReprintDetails.appInfo.initiator.slice(0, Index);
   var Name = tw.local.lgReprintDetails.appInfo.initiator.slice(Index + 1, tw.local.lgReprintDetails.appInfo.initiator.length);
}
var INITIATOR_ID = tw.local.lgReprintDetails.appInfo.initiator.split("(")[1].split(")")[0];
var INITIATOR_NAME = tw.local.lgReprintDetails.appInfo.initiator.split("(")[0];


var EndTime = null;

if (tw.local.lgReprintDetails.appInfo.status == tw.epv.ProcessAppStatus.Processing) {
   EndTime = null;
} else {
   EndTime = new TWDate();
}

AddParameter(tw.local.InstanceID);
