scripts.script:
if(tw.local.LGRequestDetails.issuanceInformation.issuarType.value == "JOINT")
{
	tw.local.JointCustomerFlag = true;
	if(tw.local.LGRequestDetails.jointCustomers == null )
	{
		tw.local.LGRequestDetails.jointCustomers = new tw.object.JointCustomers();
		tw.local.LGRequestDetails.jointCustomers.customerNo = "";
		tw.local.LGRequestDetails.jointCustomers.customerInfo = new tw.object.listOf.toolkit.NBEC.customerInfo();
	}
}
else
{
	tw.local.JointCustomerFlag = false;
}	
if(tw.local.LGRequestDetails.issuanceInformation.lgNatureType.value == "FACILITY")
{
	tw.local.FacilityFlag = true;
	if(tw.local.LGRequestDetails.facilityData == null)
	{
		tw.local.LGRequestDetails.facilityData = new tw.object.listOf.FacilityData();
		
		
	}
}
else
{
	tw.local.FacilityFlag = false;
}

tw.local.InstanceID = tw.system.currentProcessInstanceID;
tw.local.StepName = tw.system.currentTask.processActivityName;
tw.local.Status = true;
tw.local.StepUser = new tw.object.NameValuePair();
tw.local.StepUser.name = tw.system.user_fullName;
tw.local.StepUser.value = tw.system.user_loginName;

if(tw.local.LGRequestDetails == null)
{
	tw.local.LGRequestDetails = new tw.object.LgRequestDetails();
}

/////////////////  Basic Data  /////////////////////

if(tw.local.LGRequestDetails.basicData == null)
{
	tw.local.LGRequestDetails.basicData = new tw.object.BasicData();
	
	tw.local.LGRequestDetails.basicData.creationBranch = new tw.object.toolkit.TWSYS.NameValuePair();
	tw.local.LGRequestDetails.basicData.creationBranch.name = "NO Value Set Yet";
