	tw.local.LGRequestDetails.basicData.printBranch.value = "NO Value Set Yet";
	tw.local.LGRequestDetails.basicData.printCenterFlag = false;
}
if(tw.local.LGRequestDetails.basicData.printBranch == null)
{
	tw.local.LGRequestDetails.basicData.printBranch = new tw.object.toolkit.TWSYS.NameValuePair();
	tw.local.LGRequestDetails.basicData.printBranch.name = "NO Value Set Yet";
	tw.local.LGRequestDetails.basicData.printBranch.value = "NO Value Set Yet";
}
if(tw.local.LGRequestDetails.basicData.dealingBranch == null)
{
	tw.local.LGRequestDetails.basicData.dealingBranch = new tw.object.toolkit.TWSYS.NameValuePair();
	tw.local.LGRequestDetails.basicData.dealingBranch.name = "NO Value Set Yet";
	tw.local.LGRequestDetails.basicData.dealingBranch.value = "NO Value Set Yet";
}
