scripts.script:
tw.local.SQLStatement = new tw.object.listOf.SQLStatement();


tw.local.SQLCommand ="update BPM.audit_LG_Requests set   status =?,   \
  next_step =? , contract_no =? ,user_Reference =?,dealing_branch=?,\
 PRINT_Branch_CENTER_code=?,Center_flag  =?, complete_date =? , action_date=? , dealing_branch_name =?, folder_id = ? ,folder_path = ? , cash_cover_percentage=?, TASK_ID = ?   where instance_id=?";


tw.local.SQLStatement[0]= new tw.object.SQLStatement();
tw.local.SQLStatement[0].sql=tw.local.SQLCommand;   

tw.local.SQLStatement[0].parameters= new tw.object.listOf.SQLParameter();


tw.local.SQLStatement[0].parameters[0]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[0].value=tw.local.LGRequestDetails.appInfo.status;
tw.local.SQLStatement[0].parameters[0].mode="IN"; 


tw.local.SQLStatement[0].parameters[1]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[1].value=tw.local.nextStep;
tw.local.SQLStatement[0].parameters[1].mode="IN"; 

tw.local.SQLStatement[0].parameters[2]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[2].value=tw.local.LGRequestDetails.transactionInformation.contractNumber;
tw.local.SQLStatement[0].parameters[2].mode="IN"; 

tw.local.SQLStatement[0].parameters[3]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[3].value=tw.local.LGRequestDetails.transactionInformation.userReference;
tw.local.SQLStatement[0].parameters[3].mode="IN"; 



tw.local.SQLStatement[0].parameters[4]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[4].value=tw.local.LGRequestDetails.basicData.dealingBranch.value;
tw.local.SQLStatement[0].parameters[4].mode="IN"; 


tw.local.SQLStatement[0].parameters[5]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[5].value=tw.local.LGRequestDetails.basicData.printBranch.value;
tw.local.SQLStatement[0].parameters[5].mode="IN"; 

tw.local.SQLStatement[0].parameters[6]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[6].value=tw.local.LGRequestDetails.basicData.printCenterFlag==true?1:0;
tw.local.SQLStatement[0].parameters[6].mode="IN"; 

var date=new TWDate();

if(tw.local.LGRequestDetails.appInfo.status == tw.epv.ProcessAppStatus.Processing)
	{
		var EndTime = null;
	}
	else
	{
		var EndTime = date
	}
tw.local.SQLStatement[0].parameters[7]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[7].value=EndTime;
tw.local.SQLStatement[0].parameters[7].mode="IN"; 

tw.local.SQLStatement[0].parameters[8]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[8].value=date
tw.local.SQLStatement[0].parameters[8].mode="IN"; 


tw.local.SQLStatement[0].parameters[9]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[9].value=tw.local.LGRequestDetails.basicData.dealingBranch.name;
tw.local.SQLStatement[0].parameters[9].mode="IN"; 


tw.local.SQLStatement[0].parameters[10]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[10].value=tw.local.folderID;
tw.local.SQLStatement[0].parameters[10].mode="IN"; 

tw.local.SQLStatement[0].parameters[11]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[11].value=tw.local.folderPath;
tw.local.SQLStatement[0].parameters[11].mode="IN"; 
 
tw.local.SQLStatement[0].parameters[12]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[12].value=tw.local.LGRequestDetails.CashCoverPercentage;
tw.local.SQLStatement[0].parameters[12].mode="IN"; 

tw.local.SQLStatement[0].parameters[13]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[13].value=tw.local.taskID;
tw.local.SQLStatement[0].parameters[13].mode="IN"; 

tw.local.SQLStatement[0].parameters[14]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[14].value=tw.local.InstanceID;
tw.local.SQLStatement[0].parameters[14].mode="IN";

