tw.local.SQLStatement = new tw.object.listOf.SQLStatement();
tw.local.SQLCommand ="update BPM.audit_LG_Requests set   status =?,  customer_id  =?  ,  \
 main_customer_id =? ,  next_step =? , contract_no =? ,user_Reference =?,dealing_branch=?,\
 PRINT_Branch_CENTER_code=?,Center_flag  =?, complete_date =? , action_date=? , dealing_branch_name =?, TASK_ID =?   where instance_id=?";


tw.local.SQLStatement[0]= new tw.object.SQLStatement();
tw.local.SQLStatement[0].sql=tw.local.SQLCommand;   

tw.local.SQLStatement[0].parameters= new tw.object.listOf.SQLParameter();
//
//
tw.local.SQLStatement[0].parameters[0]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[0].value=tw.local.LGRequestDetails.appInfo.status;
tw.local.SQLStatement[0].parameters[0].mode="IN"; 


tw.local.SQLStatement[0].parameters[1]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[1].value=tw.local.LGRequestDetails.issuanceInformation.customerNo;
tw.local.SQLStatement[0].parameters[1].mode="IN"; 

tw.local.SQLStatement[0].parameters[2]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[2].value=tw.local.LGRequestDetails.jointCustomers.mainCustomer.customerNo;
tw.local.SQLStatement[0].parameters[2].mode="IN"; 


tw.local.SQLStatement[0].parameters[3]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[3].value=tw.local.nextStep;
tw.local.SQLStatement[0].parameters[3].mode="IN"; 

tw.local.SQLStatement[0].parameters[4]= new tw.object.SQLParameter();
tw.local.SQLStatement[0].parameters[4].value=tw.local.LGRequestDetails.transactionInformation.contractNumber;
