function setParameters (listMap,index)
{
	tw.local.branchesAndTypeQuery[index] = new tw.object.SQLStatement();
	tw.local.branchesAndTypeQuery[index].sql = index == 0 ? "SELECT BRANCH_CODE as value, BRANCH_NAME as name  From BPM.NBE_SME_LG_BRANCHES WHERE BRANCH_CODE IN (" : "SELECT CODE as value, NAME_EN as name  From BPM.LK_PRODUCTS_TYPE WHERE CODE IN ("  ;
	tw.local.branchesAndTypeQuery[index].parameters = new tw.object.listOf.SQLParameter();
	var listObj = listMap.keyArray(); 
	var len = listObj.length;
	for (var i=0; i<len; i++) 
	{
		tw.local.branchesAndTypeQuery[index].sql +=  i+1 < len ? "?," : "?)" ;
		tw.local.branchesAndTypeQuery[index].parameters[i] = new tw.object.SQLParameter();
		tw.local.branchesAndTypeQuery[index].parameters[i].value = listObj[i];
		tw.local.branchesAndTypeQuery[index].parameters[i].mode = "IN";
	}
}

