	returnAccount.accountNo = account.accountNo;
	returnAccount.accountStatus = account.accountStatus;
	returnAccount.accountTypeMsg = account.accountTypeMsg;
	returnAccount.balance = account.balance;
	returnAccount.balanceCurrency = account.balanceCurrency;
