        tw.local.cashCoverAccount = tw.local.accountList[0];
        tw.local.expenssesAccount = tw.local.accountList[0];
    }
}

// Function to check if the account class is valid
function CheckAccountClass(value) {
    

    tw.local.GNCheckEPV = tw.epv.AmendAccountClass.GN;
    if (tw.local.issuanceFilter){
        tw.local.checkEPV = tw.epv.AccountDetails.AccountClass;
        }
    else{
        tw.local.checkEPV = tw.epv.AmendAccountClass.AccountClass;
        }

    if (tw.local.checkEPV.indexOf(value.slice(0, 2)) > -1 || tw.local.GNCheckEPV.indexOf(value) > -1){
        return false;
    }
    return true;
}

