var index=0;
for(var i =0;i<tw.local.correspondenceList.listLength;i++){

	if(!tw.local.countryMap.containsKey(tw.local.correspondenceList[i].countryCode)){
		tw.local.CountriesObject[index] = new tw.object.CountriesObject();
		tw.local.CountriesObject[index].Country = tw.local.correspondenceList[i].countryCode;
		tw.local.CountriesObject[index].Banks = new tw.object.listOf.NameValuePair();
		tw.local.CountriesObject[index].Banks.insertIntoList(0, {
		name:tw.local.correspondenceList[i].bankName,
		value:tw.local.correspondenceList[i].cif+"#"+tw.local.correspondenceList[i].swiftCode
		});
		
		tw.local.countryList[index]= new tw.object.NameValuePair();
		tw.local.countryList[index].name=tw.local.correspondenceList[i].countryCode+"-"+tw.local.correspondenceList[i].countryName;
		tw.local.countryList[index].value=tw.local.correspondenceList[i].countryCode;
		index++;
		
		tw.local.bankList= new tw.object.listOf.NameValuePair();
