//		tw.local.bankList[0].name=tw.local.correspondenceList[i].bankName;
//		tw.local.bankList[0].value=tw.local.correspondenceList[i].cif+"#"+tw.local.correspondenceList[i].swiftCode;
	
		tw.local.countryMap.put(tw.local.correspondenceList[i].countryCode, tw.local.bankList);
		writeLog(" add to countryMap object key : "+tw.local.correspondenceList[i].countryCode)
		
	}else{
	
		updateBanks( tw.local.correspondenceList[i].countryCode);
		
		}
	
	
}

// add blank to the list
tw.local.countryList.insertIntoList(tw.local.countryList.listLength, {name:"" , value:""});


