function updateBanks (countryCode) {
	for (var j=0; j<tw.local.CountriesObject.listLength; j++) {
		if (tw.local.CountriesObject[j].Country == countryCode) {
			tw.local.CountriesObject[j].Banks.insertIntoList(tw.local.CountriesObject[j].Banks.listLength, {
			name:tw.local.correspondenceList[i].bankName,
			value:tw.local.correspondenceList[i].cif+"#"+tw.local.correspondenceList[i].swiftCode
		});
		}
	}
}

