tw.local.notAgain = false;
if(tw.local.existCurrency.listLength > 0)
{
	for (var i=0; i< tw.local.existCurrency.listLength; i++) 
	{
		if(tw.local.existCurrency[i] == tw.local.facilities[tw.local.Index].facilityLine.lineCurrency)
		{
			tw.local.notAgain = true;
			tw.local.facilityAmount += tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount * tw.local.existRate[i];
			tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP = tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount * tw.local.existRate[i];			
			break;
		}
	}
}

var facilityAmount = tw.local.LGequivalentAmountInEGP ;//- percentage(tw.local.LGequivalentAmountInEGP, tw.local.cashCoverPer);
if (tw.local.check)
    tw.local.checkBalance = tw.local.check;
else
    tw.local.checkBalance = tw.epv.ProcessDetails.CheckFacilitiesBalance;

var allfacilitypercentage = 0 ;//tw.local.cashCoverPer; // all percentage for the contract    ask for it



for (var i = 0; i < tw.local.facilities.listLength; i++) {
    allfacilitypercentage += tw.local.facilities[i].facilityLine.facilityPercentage;
    tw.local.perForFacilityAmount = percentage(tw.local.LGequivalentAmountInEGP, tw.local.facilities[i].facilityLine.facilityPercentage);  // new update
	
	writeLog("allfacilitypercentage" , allfacilitypercentage);	
	writeLog("tw.local.perForFacilityAmount" , tw.local.perForFacilityAmount);
	writeLog("tw.local.facilities[i].facilityLine.facilityPercentage" , tw.local.facilities[i].facilityLine.facilityPercentage);
      writeLog("tw.local.LGequivalentAmountInEGP" , tw.local.LGequivalentAmountInEGP);
      writeLog(" tw.local.facilities[i].facilityLine.avaliableAmountEGP" ,  tw.local.facilities[i].facilityLine.avaliableAmountEGP);
      writeLog(" tw.local.checkBalance" ,  tw.local.checkBalance);    
    
    if ((tw.local.perForFacilityAmount > tw.local.facilities[i].facilityLine.avaliableAmountEGP) && tw.local.checkBalance) {
        tw.local.errorMsg += "<li>" + tw.resource.IssuanceLK.TheFacilityRateFromLGAmountMustBeEqualOrLessEnglish + " for facility Liability number " + tw.local.facilities[i].cif +
            " <br> &nbsp;&nbsp;&nbsp;&nbsp;" + tw.resource.IssuanceLK.TheFacilityRateFromLGAmountMustBeEqualOrLessArabic + "</li>";
    }
}

// check if facility percentage is 100%
if (allfacilitypercentage != 100 ) {
    tw.local.errorMsg += "<li> "+tw.resource.IssuanceLK.Kindlyensurethatpercentage +" </li>";
}


//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

function percentage(num, per)
{
  writeLog("num" , num);
  writeLog("per" , per);
  return (num/100)*per;

}
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
writeLog("lg amount in EGP = "+tw.local.LGequivalentAmountInEGP);
writeLog(" percentage = "+tw.local.cashCoverPer);
writeLog(" tw.local.perForFacilityAmount = "+tw.local.perForFacilityAmount);
writeLog(" tw.local.errorMsg  "+tw.local.errorMsg);


function writeLog(msg , variable){  // vairable is optional
	var instanceID = "";
	try {instanceID = "Instance ID : "+tw.system.currentProcessInstance.id  +"  ::  ";} catch (err) {}
	variable == undefined ? variable =" " : variable = " : "+ variable ;
	var message = instanceID + tw.system.model.processApp.name  +" :: " + tw.system.serviceFlow.type +" :: "+ tw.system.serviceFlow.name +" :: "  + msg+" : " + variable;
	log.info( message);
}

tw.local.checkRate=false;

writeLog("tw.local.facilities[tw.local.Index].facilityLine.lineCurrency" , tw.local.facilities[tw.local.Index].facilityLine.lineCurrency);

if (tw.local.facilities[tw.local.Index].facilityLine.lineCurrency != "EGP") {
	for( var i =0;i<tw.local.exchangeRate.listLength;i++){
	writeLog("tw.local.exchangeRate[i].rateType" , tw.local.exchangeRate[i].rateType);
		if(tw.local.exchangeRate[i].rateType==tw.epv.Defaults.RATETYPE){
			tw.local.facilityAmount += tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount*tw.local.exchangeRate[i].saleRate;
			tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP = tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount*tw.local.exchangeRate[i].saleRate;
			var len = tw.local.existCurrency.listLength;
			tw.local.existCurrency.insertIntoList(len, tw.local.facilities[tw.local.Index].facilityLine.lineCurrency);
			tw.local.existRate.insertIntoList(len, tw.local.exchangeRate[i].saleRate); 
			tw.local.checkRate=true;
			
			writeLog("1 : tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP" , tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP);
			writeLog("1 : tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount" , tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount);
			writeLog("1 : tw.local.exchangeRate[i].saleRate" , tw.local.exchangeRate[i].saleRate);			
			break;
		}
	}	
	if(tw.local.checkRate==false){
		for( var i =0;i<tw.local.exchangeRate.listLength;i++){
		writeLog("2 : tw.local.exchangeRate[i].rateType" , tw.local.exchangeRate[i].rateType);
		
		if(tw.local.exchangeRate[i].rateType==tw.epv.Defaults.BankNote){	
			tw.local.facilityAmount += tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount*tw.local.exchangeRate[i].saleRate;
			tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP = tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount*tw.local.exchangeRate[i].saleRate;			
			var len = tw.local.existCurrency.listLength;
			tw.local.existCurrency.insertIntoList(len, tw.local.facilities[tw.local.Index].facilityLine.lineCurrency);
			tw.local.existRate.insertIntoList(len, tw.local.exchangeRate[i].saleRate); 
			tw.local.checkRate=true;
			
			writeLog("2 : tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP" , tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP);
			writeLog("2 : tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount" , tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount);
			writeLog("2 : tw.local.exchangeRate[i].saleRate" , tw.local.exchangeRate[i].saleRate);
			break;
		}
	}
	}
	
	
}
else
{
	tw.local.facilityAmount += tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount;
	writeLog("3 : tw.local.Index" , tw.local.Index)
	writeLog("3 : tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP" , tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP)
	tw.local.facilities[tw.local.Index].facilityLine.avaliableAmountEGP = tw.local.facilities[tw.local.Index].facilityLine.avaliableAmount;
}

