function checkLgType(index)
{
	if(tw.local.facilityLinesList[index].productRestricted != null && tw.local.facilityLinesList[index].productRestricted.listLength > 0)
	{
		for (var i=0; i < tw.local.facilityLinesList[index].productRestricted.listLength; i++) 
		{
			tw.local.errorCode += ","+tw.local.facilityLinesList[index].productRestricted[i].PRODUCTCODE;
			if(tw.local.facilityLinesList[index].productRestricted[i].PRODUCTCODE.trim() == tw.local.lgType)
			{ 
				return true;
			}
		}
	}
	return false;
}

