function AssignAccount(account) {
    tw.local.returnAccount = {}


    tw.local.returnAccount.accountNo = account.accountNo;
    tw.local.returnAccount.accountStatus = account.accountStatus;
    tw.local.returnAccount.accountTypeMsg = account.accountTypeMsg;
    tw.local.returnAccount.balance = account.balance;
    tw.local.returnAccount.balanceCurrency = account.balanceCurrency;
    tw.local.returnAccount.currency = account.currency;
    tw.local.returnAccount.customerNo = account.customerNo;
    tw.local.returnAccount.dormant = account.dormant;
    tw.local.returnAccount.frozen = account.frozen;
    tw.local.returnAccount.noCredit = account.noCredit;
    tw.local.returnAccount.noDebit = account.noDebit;
    tw.local.returnAccount.status = account.status;
    tw.local.returnAccount.Branch = new tw.object.NameValuePair()
    tw.local.returnAccount.Branch = account.Branch;
    return tw.local.returnAccount;
}

