		tw.local.SecionsLevels[0].Properties[index].objectTypeId = objectId;
		tw.local.SecionsLevels[0].Properties[index].value =  checkValue(value);
		index++;
	}
	 else {
	 
		log.info("can't set property : "+objectId)
		}
}
function checkValue(value) {
	try {
		if(value.value != null){
