function addContractSettlement() {
   var account;
   writeLog(" :::::: start addContractSettlement ");
   tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement = [];
   writeLog("tw.local.accountInformation", tw.local.accountInformation);
   if (validateVariable(tw.local.accountInformation, "account information ")) {
      for (var i = 0; i < tw.local.componentList.listLength; i++) {

         account = getRelevantAccount(tw.local.componentList[i].value);
         if (account) {
            writeLog("Account retrieved");
            tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement[i] = {};
            tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement[i].ACC = account.accountNo;
            if (tw.local.accountInformation.glAccount) {
               tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement[i].ACCBRN = account.Branch.value;
            } else {
               tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement[i].ACCBRN = account.accountNo.slice(0, 3);
            }
            tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement[i].ACCCCY = account.currency;
            tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement[i].COMPNT = tw.local.componentList[i].name;

            writeLog(" settlement account.accountNo :: " + account.accountNo);
            writeLog("settlement account.currency: " + account.currency);
            writeLog("settlement tw.local.AccountBranch" + tw.local.GuaranteeAmendDetailsFullReq.Settlements.Contract_Settlement[i].ACCBRN);
            writeLog("settlement tw.local.componentList[i].name " + tw.local.componentList[i].name);
         }
      }
   }
}


function getRelevantAccount(val) {
   if (val.toUpperCase() == "CC" && validateVariable(tw.local.accountInformation.cashCoverAccount, tw.resource.IssuanceLK.CashCoverAccount)) {
      return tw.local.accountInformation.cashCoverAccount;
   }
  if (val.toUpperCase() == "C" && tw.local.accountInformation.commissionAccount!=null && tw.local.accountInformation.commissionAccount.accountNo!=null && tw.local.accountInformation.commissionAccount.accountNo!='') {
      return tw.local.accountInformation.commissionAccount;
   }
   if (val.toUpperCase() == "E" && tw.local.accountInformation.expensesAccount !=null && tw.local.accountInformation.expensesAccount.accountNo!=null && tw.local.accountInformation.expensesAccount.accountNo!='') {
      return tw.local.accountInformation.expensesAccount;
   }
   return false;
}


function setDefaultValue(val, defaultValue) {

   if (val == null || val == "" || val == 0) {
      tw.local.tmpValue = defaultValue;
      return tw.local.tmpValue;
   }
   return val;
}


function validateVariable(variable, varaibleName) {
   if (variable == null) {
      tw.local.isSuccessful = false;
      tw.local.errorMsg = tw.resource.IssuanceLK.MissingVariableDataFieldNameEnglish + " [ " + varaibleName + " ] " + tw.resource.IssuanceLK.MissingVariableDataFieldNameArabic;
      return false;
   }
   return true;
}


