////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
 function getLDAPdata (CN) {
	var filter = "sAMAccountName="+CN;
	var results = ctx.search(tw.env.ldapBase, filter, controls);
	var index=0;
	
	if (results.hasMore()) {
		var searchResult = results.next();
		var attributes = searchResult.getAttributes();
		
		var groups=attributes.get("member");
		if(groups!=null){
	  	index=groups.size();
	  	var returnList =[];
	  	for(var i=0;i<index;i++){
			var CN_Name=groups.get(i).substring(3,groups.get(i).indexOf(","));
			returnList[i] = CN_Name;
	  	 }
	  	 }
	  	 
	  	 
	 }  
	 return returnList;
 }

function OpenConnection () {
	env = new Packages.java.util.Hashtable();
	url = tw.env.ldapUrl;
	env.put(javax.naming.Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory");
	env.put(javax.naming.Context.PROVIDER_URL, url);
	env.put(javax.naming.Context.SECURITY_AUTHENTICATION, "simple");
	env.put(javax.naming.Context.SECURITY_PRINCIPAL, tw.env.ldapUsername);
	env.put(javax.naming.Context.SECURITY_CREDENTIALS, tw.local.password);
	ctx = new javax.naming.directory.InitialDirContext(env);
	controls = new javax.naming.directory.SearchControls();
	controls.setSearchScope(javax.naming.directory.SearchControls.SUBTREE_SCOPE);	
}





