tw.local.query= new tw.object.SQLStatement();
tw.local.query.sql="select DECIMAL_FRANCTION from BPM.LK_Currencies where CODE = ? ;";
tw.local.query.parameters =  new tw.object.listOf.SQLParameter();
  		
tw.local.query.parameters[0] = new tw.object.SQLParameter();
tw.local.query.parameters[0].value = tw.local.currency.value;
tw.local.query.parameters[0].mode = "IN";

if(tw.local.results != null && tw.local.results.listLength > 0 && tw.local.results[0].rows != null && tw.local.results[0].rows.listLength > 0)
{  
	tw.local.fraction = tw.local.results[0].rows[0].indexedMap["DECIMAL_FRANCTION"];
}

var amountStr = tw.local.amount.toString();
if(amountStr.indexOf(".", 0) != -1)
{
	var fraction = amountStr.split(".")[1];
	if(tw.local.fraction < fraction.length)
	{
		var sub = "";
		for (var i=0; i<tw.local.fraction; i++) 
		{
			sub += fraction[i].toString();
		}
		var integer = amountStr.split(".")[0];
		amountStr = integer + "." + sub;
		tw.local.amount = Number(amountStr);
	}
	else if(tw.local.fraction > fraction.length)
	{
		var diff = tw.local.fraction - fraction.length;
		for (var i=0; i<diff; i++) 
		{
			amountStr += "0";
		}
		tw.local.amount = Number(amountStr);
	}
}  
else
{
	amountStr += ".";
	for (var i=0; i<tw.local.fraction; i++) 
	{
			amountStr += "0";
	}
	tw.local.amount = Number(amountStr);
}

