tw.local.ErrorMsg = "";
if (tw.local.documents != null) {
	for (var i=0; i<tw.local.Required_Attachment.listLength; i++) {
		for (var j=0; j<tw.local.documents.listLength; j++) {
			if(tw.local.Required_Attachment[i].Name == tw.epv.ECMDocument.LG_Letter_of_Guarantee && tw.local.Required_Attachment[i].Name == tw.local.documents[j].objectTypeId && tw.local.ErrorMsg == "")
			{
				var splitName = tw.local.documents[j].name.split(".");
				var extention = splitName[splitName.length-1];
				writeLog( "extention " ,extention);
				writeLog(""+  tw.epv.ECMDocument.LG_Contract_Type);
				if(extention.toLowerCase() != tw.epv.ECMDocument.LG_Contract_Type)
				{
					tw.local.ErrorMsg = "<li>"+tw.resource.IssuanceLK.ErrorLGContractMustBePDF+"</li>";
				}
			}

			if (tw.local.Required_Attachment[i].Name == tw.local.documents[j].objectTypeId && (!tw.local.Required_Attachment[i].Flag)) { // new and condtion
	//			tw.local.Required_Attachment[i].Flag = true;
					for (var indx=0; indx<tw.local.documents[j].properties.listLength; indx++) {

						if ((!tw.local.Required_Attachment[i].Flag) && tw.local.documents[j].properties[indx].objectTypeId == "StepName" &&tw.local.documents[j].properties[indx].value == tw.local.StepName) {
							tw.local.Required_Attachment[i].Flag = true;	 
						}
					}
				tw.local.documents.removeIndex(j--);
				
			}
		}
	}
}




